7061	    for (ModelObject *model_object : model_objects) {
7062	        auto *object = model.add_object(*model_object);
7063	        object->sort_volumes(true);
7064	        std::string object_name = object->name.empty() ? fs::path(object->input_file).filename().string() : object->name;
7065	        obj_idxs.push_back(obj_count++);
7066	
7067	        if (model_object->instances.empty()) {
7068	#ifdef AUTOPLACEMENT_ON_LOAD
7069	            object->center_around_origin();
7070	            new_instances.emplace_back(object->add_instance());
7071	#else /* AUTOPLACEMENT_ON_LOAD */
7072	            // if object has no defined position(s) we need to rearrange everything after loading
7073	            // need_arrange = true;
7074	                // add a default instance and center object around origin
7075	            object->center_around_origin();  // also aligns object to Z = 0
7076	            ModelInstance* instance = object->add_instance();
7077	
7078	            //BBS calc transformation
7079	            Geometry::Transformation t = instance->get_transformation();
7080	            instance->set_offset(Slic3r::to_3d(this->bed.build_volume().bed_center(), -object->origin_translation(2)));
7081	#endif /* AUTOPLACEMENT_ON_LOAD */
7082	        }
7083	        
7084	        //BBS: when the object is too large, let the user choose whether to scale it down
7085	        for (size_t i = 0; i < object->instances.size(); ++i) {
7086	            ModelInstance* instance = object->instances[i];
7087	            const Vec3d size = object->instance_bounding_box(i).size();
7088	            const Vec3d ratio = size.cwiseQuotient(bed_size);
7089	            const double max_ratio = std::max(ratio(0), ratio(1));
7090	            if (max_ratio > 10000) {
7091	                MessageDialog dlg(q, _L("Your object appears to be too large, do you want to scale it down to fit the print bed automatically?"), _L("Object too large"),
7092	                                  wxICON_QUESTION | wxYES);
