7096	                object->scale_mesh_after_creation(1. / max_ratio);
7097	                object->origin_translation = Vec3d::Zero();
7098	                object->center_around_origin();
7099	                scaled_down = true;
7100	                break;
7101	            }
7102	            else if (max_ratio > 10) {
7103	                MessageDialog dlg(q, _L("Your object appears to be too large, do you want to scale it down to fit the print bed automatically?"), _L("Object too large"),
7104	                                  wxICON_QUESTION | wxYES_NO);
7105	                int           answer = dlg.ShowModal();
7106	                if (answer == wxID_YES) {
7107	                    instance->set_scaling_factor(instance->get_scaling_factor() / max_ratio);
7108	                    scaled_down = true;
7109	                }
7110	            }
7111	        }
7112	
7113	        if (!auto_drop) {
