14315	
14316	    case LoadFilesType::MultipleOther: {
14317	        Plater::TakeSnapshot snapshot(this, snapshot_label);
14318	        if (handle_zips(normal_paths)) {
14319	            if (normal_paths.empty()) return true;
14320	        }
14321	        if (load_files(normal_paths, LoadStrategy::LoadModel, true).empty()) { res = false; }
14322	        break;
14323	    }
14324	
14325	    case LoadFilesType::Multiple3MFOther:
14326	        for (const auto &path : normal_paths) {
14327	            if (boost::iends_with(path.filename().string(), ".3mf")){
14328	                if (first_file.size() <= 0)
14329	                    first_file.push_back(path);
14330	                else
14331	                    tmf_file.push_back(path);
