14350	LoadType determine_load_type(std::string filename, std::string override_setting)
14351	{
14352	    std::string setting;
14353	
14354	    if (override_setting != "") {
14355	        setting = override_setting;
14356	    } else {
14357	        setting = wxGetApp().app_config->get(SETTING_PROJECT_LOAD_BEHAVIOUR);
14358	    }
14359	
14360	    if (setting == OPTION_PROJECT_LOAD_BEHAVIOUR_LOAD_GEOMETRY) {
14361	        return LoadType::LoadGeometry;
14362	    } else if (setting == OPTION_PROJECT_LOAD_BEHAVIOUR_ALWAYS_ASK) {
14363	        ProjectDropDialog dlg(filename);
14364	        if (dlg.ShowModal() == wxID_OK) {
14365	            int      choice    = dlg.get_action();
