8255	bool GUI_App::check_and_keep_current_preset_changes(const wxString& caption, const wxString& header, int action_buttons, bool* postponed_apply_of_keeped_changes/* = nullptr*/)
8256	{
8257	    if (has_current_preset_changes()) {
8258	        bool is_called_from_configwizard = postponed_apply_of_keeped_changes != nullptr;
8259	
8260	        UnsavedChangesDialog dlg(caption, header, "", action_buttons);
8261	        bool no_need_change = dlg.getUpdateItemCount() == 0 ? true : false;
8262	        if (!no_need_change && dlg.ShowModal() == wxID_CANCEL)
8263	            return false;
8264	
8265	        auto reset_modifications = [this, is_called_from_configwizard]() {
8266	            //if (is_called_from_configwizard)
8267	            //    return; // no need to discared changes. It will be done fromConfigWizard closing
8268	
8269	            PrinterTechnology printer_technology = preset_bundle->printers.get_edited_preset().printer_technology();
8270	            for (const Tab* const tab : tabs_list) {
8271	                if (tab->supports_printer_technology(printer_technology) && tab->current_preset_is_dirty())
8272	                    tab->m_presets->discard_current_changes();
8273	            }
8274	            load_current_presets(false);
8275	        };
8276	
8277	        if (dlg.discard() || no_need_change)
8278	            reset_modifications();
8279	        else  // save selected changes
8280	        {
8281	            //BBS: add project embedded preset relate logic
8282	            const auto& preset_names_and_types = dlg.get_names_and_types();
8283	            if (dlg.save_preset()) {
8284	                for (const UnsavedChangesDialog::PresetData& nt : preset_names_and_types)
8285	                    preset_bundle->save_changes_for_preset(nt.name, nt.type, dlg.get_unselected_options(nt.type), nt.save_to_project);
8286	
8287	                // if we saved changes to the new presets, we should to
8288	                // synchronize config.ini with the current selections.
