8293	                //if (!is_called_from_configwizard)
8294	                //    text += "\n\n" + _L("All modifications will be discarded for new project.");
8295	
8296	                //MessageDialog(nullptr, text).ShowModal();
8297	                reset_modifications();
8298	            }
8299	            else if (dlg.transfer_changes() && (dlg.has_unselected_options() || is_called_from_configwizard)) {
8300	                // execute this part of code only if not all modifications are keeping to the new project
8301	                // OR this function is called when ConfigWizard is closed and "Keep modifications" is selected
8302	                for (const UnsavedChangesDialog::PresetData& nt : preset_names_and_types) {
8303	                    Preset::Type type = nt.type;
8304	                    Tab* tab = get_tab(type);
8305	                    std::vector<std::string> selected_options = dlg.get_selected_options(type);
8306	                    if (type == Preset::TYPE_PRINTER) {
8307	                        auto it = std::find(selected_options.begin(), selected_options.end(), "extruders_count");
8308	                        if (it != selected_options.end()) {
8309	                            // erase "extruders_count" option from the list
8310	                            selected_options.erase(it);
8311	                            // cache the extruders count
8312	                            static_cast<TabPrinter*>(tab)->cache_extruder_cnt();
8313	                        }
8314	                    }
8315	                    std::vector<std::string> selected_options2;
8316	                    std::transform(selected_options.begin(), selected_options.end(), std::back_inserter(selected_options2), [](auto & o) {
8317	                        auto i = o.find('#');
8318	                        return i != std::string::npos ? o.substr(0, i) : o;
8319	                    });
8320	                    tab->cache_config_diff(selected_options2);
8321	                    if (!is_called_from_configwizard)
8322	                        tab->m_presets->discard_current_changes();
8323	                }
8324	                if (is_called_from_configwizard)
8325	                    *postponed_apply_of_keeped_changes = true;
8326	                else
8327	                    apply_keeped_preset_modifications();
8328	            }
8329	        }
8330	    }
