13861	        }
13862	        mz_uint num_entries = mz_zip_reader_get_num_files(&archive);
13863	        mz_zip_archive_file_stat stat;
13864	        // selected_paths contains paths and its uncompressed size. The size is used to distinguish between files with same path.
13865	        std::vector<std::pair<fs::path, size_t>> selected_paths;
13866	        FileArchiveDialog dlg(static_cast<wxWindow*>(wxGetApp().mainframe), &archive, selected_paths);
13867	        if (dlg.ShowModal() == wxID_OK)
