13874	                const fs::path& path = path_w_size.first;
13875	                size_t size = path_w_size.second;
13876	                // find path in zip archive
13877	                for (mz_uint i = 0; i < num_entries; ++i) {
13878	                    if (mz_zip_reader_file_stat(&archive, i, &stat)) {
13879	                        if (size != stat.m_uncomp_size) // size must fit
