13906	                            size_t version = 0;
13907	                            while (fs::exists(archive_dir / (final_filename + extension)))
13908	                            {
13909	                                ++version;
13910	                                final_filename = just_filename + "(" + std::to_string(version) + ")";
13911	                            }
13912	                            filename = final_filename + extension;
13913	                            fs::path final_path = archive_dir / filename;
