15035	        // Show the error with monospaced font.
15036	        show_error(this, ex.what(), true);
15037	        return;
15038	    } catch (const std::exception &ex) {
15039	        show_error(this, ex.what(), false);
15040	        return;
15041	    }
15042	    default_output_file = fs::path(Slic3r::fold_utf8_to_ascii(default_output_file.string()));
15043	    AppConfig 				&appconfig 				 = *wxGetApp().app_config;
15044	    RemovableDriveManager 	&removable_drive_manager = *wxGetApp().removable_drive_manager();
15045	    // Get a last save path, either to removable media or to an internal media.
15046	    std::string      		 start_dir 				 = appconfig.get_last_output_dir(default_output_file.parent_path().string(), prefer_removable);
15047	    if (prefer_removable) {
15048	        // Returns a path to a removable media if it exists, prefering start_dir. Update the internal removable drives database.
15049	        start_dir = removable_drive_manager.get_removable_drive_path(start_dir);
15050	        if (start_dir.empty())
15051	            // Direct user to the last internal media.
15052	            start_dir = appconfig.get_last_output_dir(default_output_file.parent_path().string(), false);
15053	    }
15054	
15055	    fs::path output_path;
15056	    {
15057	        std::string ext = default_output_file.extension().string();
15058	        wxFileDialog dlg(this, (printer_technology() == ptFFF) ? _L("Save G-code file as:") : _L("Save SLA file as:"),
15059	            start_dir,
15060	            from_path(default_output_file.filename()),
15061	            GUI::file_wildcards((printer_technology() == ptFFF) ? FT_GCODE : FT_SL1, ext),
15062	            wxFD_SAVE | wxFD_OVERWRITE_PROMPT
15063	        );
15064	        if (dlg.ShowModal() == wxID_OK) {
15065	            output_path = into_path(dlg.GetPath());
15066	            while (has_illegal_filename_characters(output_path.filename().string())) {
15067	                show_error(this, _L("The provided file name is not valid.") + "\n" +
15068	                    _L("The following characters are not allowed by a FAT file system:") + " <>:/\\|?*\"");
15069	                dlg.SetFilename(from_path(output_path.filename()));
15070	                if (dlg.ShowModal() == wxID_OK)
15071	                    output_path = into_path(dlg.GetPath());
15072	                else {
15073	                    output_path.clear();
15074	                    break;
15075	                }
15076	            }
15077	        }
15078	    }
15079	
15080	    if (! output_path.empty()) {
15081	        bool path_on_removable_media = removable_drive_manager.set_and_verify_last_save_path(output_path.string());
15082	        //bool path_on_removable_media = false;
15083	        p->notification_manager->new_export_began(path_on_removable_media);
15084	        p->exporting_status = path_on_removable_media ? ExportingStatus::EXPORTING_TO_REMOVABLE : ExportingStatus::EXPORTING_TO_LOCAL;
15085	        p->last_output_path = output_path.string();
