15088	        // Storing a path to AppConfig either as path to removable media or a path to internal media.
15089	        // is_path_on_removable_drive() is called with the "true" parameter to update its internal database as the user may have shuffled the external drives
15090	        // while the dialog was open.
15091	        appconfig.update_last_output_dir(output_path.parent_path().string(), path_on_removable_media);
15092	
15093	        try {
15094	            json j;
15095	            auto printer_config = Slic3r::GUI::wxGetApp().preset_bundle->printers.get_edited_preset_with_vendor_profile().preset;
15096	            if (printer_config.is_system) {
