1658	{
1659	    if (title == _L("Object too small"))
1660	        return units == UnitChoice::ConvertIfTiny ? wxID_YES : wxID_NO;
1661	    if (title == _L("Object too large"))
1662	        return scale_oversized ? wxID_YES : wxID_NO;
1663	    if (title == wxString(SLIC3R_APP_FULL_NAME) + " - " + _L("Save"))
1664	        return discard_unsaved ? wxID_NO : wxID_CANCEL;
1665	    // Cancelling the STEP meshing question aborts the whole load; ok meshes
1666	    // with the precision the dialog opened with, Orca's own default.
1667	    if (dynamic_cast<StepMeshDialog*>(&dialog) != nullptr)
1668	        return wxID_OK;
1669	    // Orca's message dialogs read yes or ok; its OBJ colour dialog reads ok,
1670	    // and cancel keeps its defaults.
1671	    return dynamic_cast<MsgDialog*>(&dialog) != nullptr ? wxID_NO : wxID_CANCEL;
